def api_gql(stmt: str) -> runtime.GQLOperation | slots.GQLFragment[pydantic.BaseModel, Any] | runtime.GQLTemplate:
    if stmt not in _statement_factories:
        msg = "unknown GraphQL statement passed to api_gql; "
